    ["Invite ta team, qui accepte seule :"] = "Invites your team, who accept on their own:",
    ["Dès que tes persos ont rejoint le groupe après « Inviter la team », le butin passe en accès libre (tu dois être chef)."] = "As soon as your characters have joined the group after \"Invite team members\", loot switches to free for all (you must be the leader).",
    ["%s part changer de couche : je quitte le groupe (Swap layer en groupe)."] = "%s is leaving to change layer: leaving the group (Swap Layer in group).",
    ["Invitation de %s acceptée (Swap layer en groupe)."] = "Invite from %s accepted (Swap Layer in group).",
    ["Je montre les PNJ autour pour que LayerSwap lise ta couche : reclique sur « Swap layer » dans une seconde."] = "Showing the NPCs around so LayerSwap can read your layer: click \"Swap layer\" again in a second.",
    ["Aucun perso à inviter : ajoute tes persos dans la liste des Marqueurs (ou clique sur « Swap layer » quand tu es groupé avec eux)."] = "No character to invite: add your characters to the Markers list (or click \"Swap layer\" while grouped with them).",
    ["%s (module %s)"] = "%s (%s module)",
    ["Pour profiter de tous les modules, installe aussi : %s. Disponibles sur CurseForge."] = "To use every module, also install: %s. Available on CurseForge.",
    ["%s a besoin de l'addon %s : installe-le et active-le, sinon ce module ne fait rien."] = "%s needs the %s addon: install and enable it, otherwise this module does nothing.",
    ["Points de vol"] = "Flight points",
    ["Tous les maîtres de vol sur la carte du monde, même ceux que tu n'as pas encore découverts : en orange ceux qui restent à prendre."] = "Every flight master on the world map, even the ones you have not discovered yet: those still to take in orange.",
    ["Afficher les points de vol sur la carte"] = "Show flight points on the map",
    ["Ceux de ta faction et les neutres. Ceux que tu connais sont notés quand tu ouvres la carte d'un maître de vol."] = "Your faction's and neutral ones. Known ones are recorded when you open a flight master's map.",
    ["Aussi ceux que je connais"] = "Also the ones I know",
    ["Décoche pour ne voir que ceux qui restent à découvrir."] = "Untick to see only those still to discover.",
    ["Point de vol connu"] = "Known flight point",
    ["Point de vol à découvrir"] = "Flight point to discover",
    ["Créer la macro de tir"] = "Create the shoot macro",
    ["Impossible en combat : réessaie après le combat."] = "Not possible in combat: try again after the fight.",
    ["Plus de place pour une macro de personnage : libères-en une et réessaie."] = "No room for a character macro: free one and try again.",
    ["Macro « SG Tir » prête : elle est sur ton curseur, pose-la sur ta barre et appuie dessus à chaque arrêt."] = "\"SG Tir\" macro ready: it is on your cursor, drop it on your bar and press it each time you stop.",
    ["Signal « arrête-toi »"] = "\"Stop now\" signal",
    ["Le remplissage change de couleur pile au moment de t'arrêter pour que le tir parte."] = "The fill changes colour exactly when you must stop for the shot to fire.",
    ["En tirant"] = "While shooting",
    ["En combat"] = "In combat",
    ["Toujours"] = "Always",
    ["Afficher la barre"] = "Show the bar",
    ["En tirant : seulement quand le tir auto ou la baguette est actif. En combat : aussi pendant tout le combat."] = "While shooting: only while Auto Shot or your wand is on. In combat: also for the whole fight.",
    ["Pour la barre SuperRsk. Les textures de tes autres addons (SharedMedia…) sont proposées aussi."] = "For the SuperRsk bar. Bar textures from your other addons (SharedMedia…) are offered too.",
    ["Couleur du remplissage"] = "Fill colour",
    ["Afficher le temps avant le tir"] = "Show time until the shot",
    ["Les secondes qui restent avant le prochain tir, sur la barre SuperRsk."] = "The seconds left before the next shot, on the SuperRsk bar.",
    ["Auto Shot / Wand : réservé aux chasseurs, mages, prêtres et démonistes."] = "Auto Shot / Wand: for hunters, mages, priests and warlocks only.",
    ["armement mesuré du tir auto / de la baguette"] = "measured Auto Shot / wand wind-up",
    ["Afficher la barre de tir"] = "Show the shot bar",
    ["Elle apparaît quand tu lances le tir auto ou la baguette. Bouton « Déplacer » pour la placer."] = "It appears when you start Auto Shot or your wand. \"Move\" button to place it.",
    ["SuperRsk"] = "SuperRsk's",
    ["Celle du jeu"] = "The game's",
    ["Barre utilisée"] = "Bar used",
    ["Celle du jeu : la zone rouge se pose sur la barre de tir de Blizzard (à activer dans Options > Options avancées, puis à placer en mode Édition)."] = "The game's: the red zone goes on Blizzard's swing timer (turn it on in Options > Advanced Options, then place it in Edit Mode).",
    ["Barre de tir"] = "Shot bar",
    ["Auto (mesurée)"] = "Auto (measured)",
    ["Durée de l'armement du tir"] = "Shot wind-up time",
    ["Auto : mesurée sur tes tirs (la bêta a un bug qui l'écourte à ~0,1 s ; la zone suivra quand Blizzard le corrigera). /sg tir affiche la mesure."] = "Auto: measured on your shots (a beta bug cuts it to ~0.1 s; the zone will follow when Blizzard fixes it). /sg tir shows the measurement.",
    ["Compter ma latence"] = "Account for my latency",
    ["La zone commence plus tôt de ta latence : ton arrêt arrive au serveur à temps."] = "The zone starts earlier by your latency, so your stop reaches the server in time.",
    ["Avance en plus (ms)"] = "Extra lead (ms)",
    ["Apparence"] = "Appearance",
    ["Couleur de la zone"] = "Zone colour",
    ["Opacité de la zone"] = "Zone opacity",
    ["Elle s'éclaire quand tu es dedans avec le tir auto actif."] = "It brightens while you are inside it with Auto Shot on.",
    ["Pulser quand un tir attend"] = "Pulse while a shot is due",
    ["Tu as bougé pendant l'armement : la zone reste allumée et pulse jusqu'au départ du tir."] = "You moved during the wind-up: the zone stays lit and pulses until the shot fires.",
    ["%s s (%d mesures)"] = "%s s (%d measurements)",
    ["Auto Shot / Wand en veille : l'addon ShotWindow est encore activé (désactive-le pour utiliser le module)."] = "Auto Shot / Wand on standby: the ShotWindow addon is still enabled (disable it to use the module).",
    ["armement du tir : %s, zone utilisée : %s s"] = "shot wind-up: %s, zone in use: %s s",
    ["pas encore mesuré"] = "not measured yet",
    ["Garde tes barres d'action sur le plus haut rang de chaque sort : quand tu apprends un nouveau rang, les boutons de l'ancien passent au nouveau, au même endroit (barres de la manette comprises)."] = "Keeps your action bars on the highest rank of each spell: when you learn a new rank, buttons holding the old one switch to it, in the same slot (gamepad bars included).",
    ["Monter les sorts au plus haut rang"] = "Upgrade spells to the highest rank",
    ["À la connexion et à chaque sort appris, hors combat. Seulement les boutons de sort : macros, objets et cases vides ne bougent pas. Jamais vers un rang plus bas."] = "At login and whenever you learn a spell, out of combat. Only spell buttons: macros, items and empty slots never move. Never to a lower rank.",
    ["Annoncer les changements dans le chat"] = "Report changes in chat",
    ["%s → %s (%d bouton)"] = "%s → %s (%d button)",
    ["%s → %s (%d boutons)"] = "%s → %s (%d buttons)",
    ["Auto Loot en veille : l'addon SuperAutoLoot est encore activé (désactive-le pour utiliser le module)."] = "Auto Loot on standby: the SuperAutoLoot addon is still enabled (disable it to use the module).",
    ["Butin ramassé"] = "Looted items",
    ["Ramassage instantané"] = "Instant looting",
    ["Vide le corps dès qu'il s'ouvre (avec le ramassage automatique, ou Maj + clic droit selon tes réglages du jeu)."] = "Empties the corpse as soon as it opens (with auto loot, or Shift + right-click depending on your game settings).",
    ["Ramassage automatique du jeu"] = "Game auto loot",
    ["Active l'option « Butin automatique » du jeu pour ce personnage à chaque connexion."] = "Turns on the game's \"Auto Loot\" option for this character at each login.",
    ["Confirmer seul les objets « lié quand ramassé »"] = "Auto-confirm \"bind on pickup\" items",
    ["Seulement quand tu joues seul : en groupe, le jeu te demande toujours."] = "Only when solo: in a group, the game always asks.",
    ["Sons"] = "Sounds",
    ["Son quand les sacs sont pleins"] = "Sound when bags are full",
