    ["+%s · emplacement vide"] = "+%s · empty slot",
    ["emplacement vide"] = "empty slot",
    ["Météo"] = "Weather",
    ["repère : %s (%d, %d)"] = "waypoint: %s (%d, %d)",
    ["Avec l'addon Spy : un clic sur un ennemi de sa liste le cible et pose un ping dessus, visible par ton groupe. Le jeu ne laisse pas un addon pinger seul : c'est ton clic qui le déclenche."] = "With the Spy addon: a click on an enemy in its list targets them and pings them, seen by your group. The game does not let an addon ping on its own: your click does it.",
    ["Pinger l'ennemi cliqué dans Spy"] = "Ping the enemy clicked in Spy",
    ["Clic gauche sur la ligne. Maj + clic et Ctrl + clic gardent leur rôle dans Spy (liste KOS, ignorés). Rien si l'ennemi est trop loin pour être ciblé."] = "Left-click the row. Shift-click and Ctrl-click keep their Spy role (KOS list, ignore). Nothing if the enemy is too far to be targeted.",
    ["Attention"] = "Warning",
    ["Attaque"] = "Attack",
    ["Type de ping"] = "Ping type",
    ["Repère sur le lieu de la rencontre"] = "Waypoint where you met them",
    ["Le jeu ne donne jamais la position d'un ennemi : le repère va là où TU étais quand Spy l'a détecté, pas là où il est maintenant. TomTom s'il est installé, sinon le repère du jeu."] = "The game never gives an enemy's position: the waypoint goes where YOU were when Spy detected them, not where they are now. TomTom if installed, otherwise the game's waypoint.",
    ["Brouillard"] = "Fog",
    ["graphismes : changés à la sortie du combat"] = "graphics: changed when combat ends",
    ["%s : activé (coupe-le pour retrouver tes réglages)"] = "%s: on (turn it off to get your settings back)",
    ["%s : tes réglages d'avant sont revenus"] = "%s: your previous settings are back",
    ["Optimiser mes graphismes pour les FPS"] = "Optimize my graphics for FPS",
    ["Ombres correctes, textures hautes, effets au sol gardés. Coupés ou baissés : distance de vue, détails du décor, herbes, eau, occlusion ambiante, effets de profondeur, contours, densité des sorts des autres, réverbération du son. Mêmes réglages en raid et donjon, image plus nette. Tes retouches ensuite restent."] = "Fair shadows, high textures, ground effects kept. Off or lowered: view distance, environment detail, ground clutter, liquids, ambient occlusion, depth effects, outlines, other players' spell density, sound reverb. Same settings in raids and dungeons, sharper image. Your later tweaks stay.",
    ["Météo et brouillard"] = "Weather and fog",
    ["Retire la pluie, la neige, les tempêtes de sable et le brouillard : la vue reste dégagée et le jeu plus fluide. Coupe le module et tes réglages d'avant reviennent."] = "Removes rain, snow, sandstorms and fog: a clear view and a smoother game. Turn the module off and your previous settings come back.",
    ["Activer"] = "Turn on",
    ["Retirer la météo"] = "Remove weather",
    ["Pluie, neige, tempêtes (weatherDensity 0)."] = "Rain, snow, storms (weatherDensity 0).",
    ["Retirer le brouillard"] = "Remove fog",
    ["Le brouillard volumétrique (volumeFog 0)."] = "Volumetric fog (volumeFog 0).",
    ["Bouton sur la minicarte"] = "Minimap button",
    -- Menu principal (UI/Menu.lua, UI/Controles.lua, UI/Minimap.lua)
    ["Accueil"] = "Home",
    ["Réglages"] = "Settings",
    ["À propos"] = "About",
    ["Module"] = "Add-ons",
    ["Propose d'équiper les objets meilleurs que les tiens. Tu choisis jusqu'à quelle qualité les objets « lié quand équipé » sont proposés."] = "Offers to equip items better than yours. You choose up to which quality bind-on-equip items are suggested.",
    ["Tout s'applique tout de suite et reste enregistré."] = "Everything applies right away and is saved.",
    ["Positions"] = "Window positions",
    ["COMMANDES"] = "COMMANDS",
    ["CRÉDITS"] = "CREDITS",
    ["Icônes : Lucide (licence ISC)."] = "Icons: Lucide (ISC license).",
    ["Police : Archivo (SIL Open Font License 1.1)."] = "Font: Archivo (SIL Open Font License 1.1).",
    ["Clic gauche : menu principal"] = "Left click: main menu",
    ["Glisser : déplacer ce bouton"] = "Drag: move this button",
    -- Marqueurs
    ["Marqueurs"] = "Raid markers",
    ["Un symbole de raid au-dessus de ta tête, et sur les personnes de ta liste quand elles sont dans ton groupe. Le jeu ne laisse pas un addon les poser seul : un appui sur ta touche (Raccourcis > SuperRsk) ou sur la macro « SG Symboles » les pose tous."] = "A raid marker above your head, and on the people in your list when they are in your group. The game does not let an add-on place them by itself: one press of your key (Key Bindings > SuperRsk) or of the \"SG Symboles\" macro places them all.",
    ["Poser les symboles"] = "Place the markers",
    ["En raid, seuls le chef et ses assistants peuvent poser des symboles : sinon rien ne se passe."] = "In a raid, only the leader and assistants can place markers: otherwise nothing happens.",
    ["Mon symbole"] = "My marker",
    ["Un symbole ne peut être que sur une personne à la fois : le tien passe avant ceux de la liste."] = "A marker can only be on one person at a time: yours comes before the list.",
    ["Créer la macro"] = "Create the macro",
    ["Macro « SG Symboles » prête : elle est sur ton curseur, pose-la sur ta barre. Un appui pose tes symboles."] = "\"SG Symboles\" macro ready: it is on your cursor, put it on your bar. One press places your markers.",
    ["Poser mes symboles"] = "Place my markers",
    ["Meilleure récompense pour toi : %s"] = "Best reward for you: %s",
    ["Commande inconnue : %s (/sg, /sg move, tir, spe, sacs, peche, menage, dr)."] = "Unknown command: %s (/sg, /sg move, tir, spe, bags, fish, cleanup, dr).",
    ["Clic : menu principal. Glisser : déplacer."] = "Click: main menu. Drag: move.",
    ["Quand une quête propose plusieurs récompenses : la meilleure pour toi est sélectionnée (sinon la plus chère à revendre). Tu cliques « Terminer »."] = "When a quest offers several rewards: the best one for you is selected (otherwise the most valuable to sell). You click \"Complete\".",
    ["Remettre les barres, les fenêtres et le bouton de la minicarte à leur place ?"] = "Put the bars, windows and the minimap button back in place?",
    ["Version %s · la boîte à outils maison de SuperRsk et ses potes."] = "Version %s · SuperRsk and friends' homemade toolbox.",
    ["ce menu (aussi /srsk)"] = "this menu (also /srsk)",
    ["déplacer les barres et fenêtres"] = "move the bars and windows",
    ["arbre de talents retenu par Auto Equip"] = "talent tree used by Auto Equip",
    ["Bibliothèques : LibStub, CallbackHandler-1.0, FlightMasterData."] = "Libraries: LibStub, CallbackHandler-1.0, FlightMasterData.",
    ["Interaction rapide"] = "Quick interact",
    ["Le jeu vise tout seul l'objet le plus proche autour de toi (filon, plante, coffre, objet de quête, bouchon de pêche), jusqu'à 20 m, avec une icône au-dessus. Un appui sur ta touche « Interagir avec la cible » (Options > Raccourcis) le prend. Coupe le module et tes réglages d'avant reviennent."] = "The game targets on its own the nearest object around you (ore, herb, chest, quest object, fishing bobber), up to 20 yards, with an icon above it. Pressing your \"Interact with target\" key (Options > Keybindings) takes it. Turn the module off and your previous settings come back.",
    ["Viser les objets autour de moi"] = "Target the objects around me",
    ["Ciblage souple sur 360°, 20 m, objets compris (bouchon de pêche aussi), icône au-dessus de l'objet visé. Sans touche « Interagir avec la cible », rien ne se prend : assigne-la dans Options > Raccourcis."] = "Soft targeting over 360°, 15 m, objects included (even slightly out of range, like the fishing bobber), icon and nameplate above the targeted object. Without an \"Interact with target\" key nothing is taken: bind it in Options > Keybindings.",
    ["Écouter le son"] = "Play the sound",
    ["Général"] = "Master",
    ["Effets"] = "Effects",
    ["Musique"] = "Music",
    ["Ambiance"] = "Ambience",
    ["Dialogues"] = "Dialog",
    ["Canal du son"] = "Sound channel",
    ["Le son suit le volume de ce canal (Options du jeu > Son). Général : toujours entendu tant que le son du jeu est allumé. Effets : baisse avec les bruitages. Musique : se coupe si tu coupes la musique."] = "The sound follows this channel's volume (Game options > Sound). Master: always heard while game sound is on. Effects: goes down with sound effects. Music: muted if you mute the music.",
    ["Son introuvable : le jeu ne voit les nouveaux fichiers d'un addon qu'au lancement. Quitte et relance complètement le jeu (un /reload ne suffit pas)."] = "Sound not found: the game only sees an addon's new files at launch. Quit and restart the game completely (a /reload is not enough).",
    ["Les petits plus de Tsquid. Coupe le module pour tout arrêter d'un coup."] = "Tsquid's little extras. Turn the module off to stop everything at once.",
    ["Activer Tsquid Area"] = "Enable Tsquid Area",
    ["Son sur coup critique"] = "Sound on critical hit",
    ["Un son de sabre laser quand ta cible encaisse un coup critique. Sur Forever, le jeu ne dit pas de qui vient le critique : en groupe, ceux des autres sur ta cible sonnent aussi."] = "A lightsaber sound when your target takes a critical hit. On Forever, the game does not say whose crit it is: in a group, other players' crits on your target play it too.",
    ["points de talents"] = "talent points",
    ["rôle de la spécialisation"] = "specialization role",
    ["choisi dans les réglages"] = "chosen in the settings",
    ["rôle"] = "role",
    ["Arbre de talents"] = "Talent tree",
    ["Automatique"] = "Automatic",
    ["Auto : d'après ta spécialisation (rôle). Quand le rôle ne suffit pas (guerrier, druide ou chaman dégâts), choisis ton arbre. Guerrier 1 Armes, 2 Fureur, 3 Protection · Paladin 1 Sacré, 2 Protection, 3 Vindicte · Chasseur 1 Maîtrise des bêtes, 2 Précision, 3 Survie · Voleur 1 Assassinat, 2 Combat, 3 Finesse · Prêtre 1 Discipline, 2 Sacré, 3 Ombre · Chaman 1 Élémentaire, 2 Amélioration, 3 Restauration · Mage 1 Arcanes, 2 Feu, 3 Givre · Démoniste 1 Affliction, 2 Démonologie, 3 Destruction · Druide 1 Équilibre, 2 Farouche, 3 Restauration. /sg spe montre ce qui est retenu."] = "Auto: from your specialization (role). When the role is not enough (damage warrior, druid or shaman), pick your tree. Warrior 1 Arms, 2 Fury, 3 Protection · Paladin 1 Holy, 2 Protection, 3 Retribution · Hunter 1 Beast Mastery, 2 Marksmanship, 3 Survival · Rogue 1 Assassination, 2 Combat, 3 Subtlety · Priest 1 Discipline, 2 Holy, 3 Shadow · Shaman 1 Elemental, 2 Enhancement, 3 Restoration · Mage 1 Arcane, 2 Fire, 3 Frost · Warlock 1 Affliction, 2 Demonology, 3 Destruction · Druid 1 Balance, 2 Feral, 3 Restoration. /sg spe shows what is used.",
    ["par défaut : arbre indécis ou niveau < 10"] = "default: undecided tree or level < 10",
    ["poids"] = "weights",
    ["jeu"] = "game",
    ["Détection Spy"] = "Spy detection",
    ["Meilleure détection (plaques ennemies toujours affichées)"] = "Better detection (enemy nameplates always shown)",
    ["Sur Forever, Spy ne voit un ennemi que par sa plaque de nom, ta cible ou ta souris : le journal de combat est fermé aux addons. Les plaques ennemies restent affichées hors combat et portent plus loin, Spy détecte dès qu'un ennemi entre dans ton champ. Coupe et tes réglages d'avant reviennent."] = "On Forever, Spy only sees an enemy through their nameplate, your target or your mouse: the combat log is closed to addons. Enemy nameplates stay shown out of combat and reach further, so Spy detects as soon as an enemy comes into view. Turn it off and your previous settings come back.",
    ["Victoires honorables"] = "Honorable kills",
    ["Remettre le widget à sa place"] = "Put the widget back in place",
    ["Un petit widget déplaçable : tes victoires honorables (et ton rang s'il y en a un). Survole-le pour le classement de ta guilde : partagé entre les membres qui ont SuperRsk, et relevé en passant près des autres (inspection, hors combat). Clique dessus pour le classement complet."] = "A small movable widget: your honorable kills (and your rank if there is one). Hover it for your guild's ranking: shared between members who run SuperRsk, and read when you walk past the others (inspect, out of combat). Click it for the full ranking.",
    ["Afficher le widget"] = "Show the widget",
